from pathlib import Path
import base64, gzip

ROOT = Path('buildsrc/quiet-diary')


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding='utf-8')
    if old not in text:
        raise SystemExit(f'expected block not found in {path}: {old[:90]!r}')
    path.write_text(text.replace(old, new, 1), encoding='utf-8')


def write_gz64(rel: str, payload: str) -> None:
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(payload)))

FILES = {
'app/src/main/res/layout/activity_night_assistant.xml': '',
'app/src/main/res/layout/activity_practice_hub.xml': '',
'app/src/main/res/layout/activity_archive.xml': '',
'app/src/main/res/drawable/premium_showcase_blue.xml': '',
'app/src/main/res/drawable/premium_showcase_warm.xml': '',
'app/src/main/res/drawable/premium_empty_background.xml': ''
}

for rel, payload in FILES.items():
    write_gz64(rel, payload)

